// Pattern: Fail fast with clear validation errors
const body = msg.payload;
const errors = [];

if (!body || typeof body !== 'object') {
    errors.push('Body must be a JSON object');
} else {
    if (!body.id || typeof body.id !== 'string') {
        errors.push('id must be a non-empty string');
    }
    if (!body.action || !['create', 'update', 'delete'].includes(body.action)) {
        errors.push('action must be one of: create, update, delete');
    }
    if (body.data !== undefined && typeof body.data !== 'object') {
        errors.push('data must be an object if provided');
    }
}

if (errors.length > 0) {
    // Output 2: validation failed
    msg.statusCode = 400;
    msg.payload = { success: false, errors };
    return [null, msg];
}

// Output 1: valid
msg._retries = 0;
return [msg, null];

const statusCode = msg.statusCode;

if (statusCode >= 200 && statusCode < 300) {
    // Success
    msg.payload = {
        success: true,
        result: msg.payload,
        statusCode
    };
    msg.statusCode = 200;
    return [msg, null];  // output 1: success
}

if (statusCode === 429 || statusCode >= 500) {
    // Transient error — trigger retry
    return [null, msg];  // output 2: retry
}

// Permanent error (4xx)
msg.payload = {
    success: false,
    error: 'External API returned an error',
    statusCode,
    detail: msg.payload
};
msg.statusCode = 502;
return [msg, null];  // output 1: permanent error → send to client

const MAX_RETRIES = parseInt(env.get('MAX_RETRIES')) || 3;
const BASE_DELAY_MS = 1000;

msg._retries = (msg._retries || 0) + 1;

if (msg._retries > MAX_RETRIES) {
    node.warn(`Max retries (${MAX_RETRIES}) exceeded for ${msg._msgid}`);
    // Route to dead letter queue
    msg._dlq_reason = `Exceeded max retries (${MAX_RETRIES}): HTTP ${msg.statusCode}`;
    return [null, msg];  // output 2: dead letter queue
}

// Exponential backoff: 1s, 2s, 4s...
msg.delay = BASE_DELAY_MS * Math.pow(2, msg._retries - 1);
node.warn(`Retry ${msg._retries}/${MAX_RETRIES} in ${msg.delay}ms (HTTP ${msg.statusCode})`);
return [msg, null];  // output 1: retry

// Dead Letter Queue: serialize failed message for later reprocessing
const dlqEntry = {
    id: msg._msgid,
    timestamp: new Date().toISOString(),
    reason: msg._dlq_reason || 'Unknown error',
    retries: msg._retries || 0,
    original_payload: msg.payload,
    topic: msg.topic || null
};

msg.payload = JSON.stringify(dlqEntry) + '\n';
msg.filename = env.get('DLQ_FILE_PATH') || '/tmp/nodered-dlq.jsonl';
msg.encoding = 'utf8';
return msg;

// Log the error with full context
node.error(`Unhandled error in '${msg.error.source.name}' (${msg.error.source.type}): ${msg.error.message}`);

const alert = {
    severity: 'ERROR',
    flow: 'Error Handling Demo',
    node_id: msg.error.source.id,
    node_name: msg.error.source.name,
    node_type: msg.error.source.type,
    message: msg.error.message,
    timestamp: new Date().toISOString()
};

msg.payload = alert;
return msg;
